B.dmv=new A.a1(B.cr6,B.b2R)
B.cdR=s(["analise","sangue","colesterol","glicemia","glicose","hba1c","trigliceridos","perfil lipidico","hemograma"],t.s)
B.bts=s(["Jejum de 8 a 12 horas (s\xf3 \xe1gua). Para a glicemia, os triglic\xe9ridos e o colesterol \xe9 o habitual.","Medica\xe7\xe3o: tome a de todos os dias com um pouco de \xe1gua, salvo indica\xe7\xe3o contr\xe1ria do m\xe9dico.","Evite \xe1lcool e exerc\xedcio intenso nas 24 horas anteriores; durma bem."],t.s)
B.b2T=new A.v3("An\xe1lises ao sangue",B.bts)
B.dn0=new A.a1(B.cdR,B.b2T)
B.c57=s(["mapa","holter","monitorizacao ambulatoria"],t.s)
B.c8K=s(["Use roupa larga; n\xe3o molhe o aparelho e evite tomar banho de imers\xe3o.","Fa\xe7a o dia normal, sem alterar rotinas nem medica\xe7\xe3o, e mantenha o bra\xe7o estendido e parado durante cada medi\xe7\xe3o.","Anote as horas de sono, de medicamentos e se teve sintomas."],t.s)
B.b2U=new A.v3("MAPA ou Holter (24 horas)",B.c8K)
B.dkB=new A.a1(B.c57,B.b2U)
B.cmD=s(["ecocardiograma","eco cardio"],t.s)
B.ciZ=s(["N\xe3o precisa de jejum nem de prepara\xe7\xe3o especial.","Leve exames card\xedacos anteriores; use roupa f\xe1cil de tirar na parte de cima."],t.s)
B.b2Q=new A.v3("Ecocardiograma",B.ciZ)
B.dlZ=new A.a1(B.cmD,B.b2Q)
B.cqr=s(["eletrocardiograma","ecg","prova de esforco"],t.s)
